                        //             },
                        //             "ATOM.S": {
                        //                 "aclass": "currency",
                        //                 "altname": "ATOM.S",
                        //                 "decimals": 8,
                        //                 "display_decimals": 6,
                        //                 "status": "enabled",
                        //             },
                        //             "XXBT": {
