                        //                 "margin_rate": 0.01,
                        //                 "status": "enabled",
                        //             },
                        //             "XETH": {
                        //                 "aclass": "currency",
                        //                 "altname": "ETH",
                        //                 "decimals": 10,
                        //                 "display_decimals": 5
                        //                 "margin_rate": 0.02,
                        //                 "status": "enabled",
                        //             },
                        //             "XBT.M": {
                        //                 "aclass": "currency",
                        //                 "altname": "XBT.M",
